query HelpItem($size: Int, $from: Int) {
  resourceSearch(contentType: [HELP], size: $size, from: $from, searchable: true) {
    documents {
      total
      results {
        __typename
        ... on Help {
          ...HelpResult
        }
      }
    }
  }
}

fragment HelpResult on Help {
  id
  identifier
  title
  body
  excerpt
}
